          "plainKo": "헬스케어 종목들은 위의 AI 이야기와 아무 상관이 없는, 완전히 다른 이유로 오른 별개 무리입니다. 신약이 잘 팔려 실적이 좋아졌거나, 회사를 사고파는 인수합병이 늘었거나, 금리가 내려가면 임상시험 자금을 싸게 빌릴 수 있다는 기대 때문입니다.",
